"use client";

import * as React from "react";
import { Dialog } from "@base-ui/react/dialog";

import { cn } from "@/lib/utils";
import { useMediaQuery } from "@/hooks/use-media-query";
import {
  BottomSheetClose,
  BottomSheetContent,
  BottomSheetDescription,
  BottomSheetHeader,
  BottomSheetRoot,
  BottomSheetTitle,
  BottomSheetTrigger,
} from "@/components/ui/bottom-sheet";

type ResponsiveDialogContextValue = { mobile: boolean };
const ResponsiveDialogContext = React.createContext<ResponsiveDialogContextValue | null>(null);

function useResponsiveDialogContext() {
  const context = React.useContext(ResponsiveDialogContext);
  if (!context) throw new Error("ResponsiveDialog parts must be used inside ResponsiveDialog.");
  return context;
}

export type ResponsiveDialogProps = {
  children: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  breakpoint?: string;
};

export function ResponsiveDialogRoot({
  children,
  open,
  defaultOpen = false,
  onOpenChange,
  breakpoint = "(max-width: 47.999rem)",
}: ResponsiveDialogProps) {
  const mobile = useMediaQuery(breakpoint);
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
  const currentOpen = open ?? uncontrolledOpen;
  const setOpen = (nextOpen: boolean) => {
    if (open === undefined) setUncontrolledOpen(nextOpen);
    onOpenChange?.(nextOpen);
  };

  const content = (
    <ResponsiveDialogContext.Provider value={{ mobile }}>
      {children}
    </ResponsiveDialogContext.Provider>
  );

  return mobile ? (
    <BottomSheetRoot open={currentOpen} onOpenChange={setOpen}>{content}</BottomSheetRoot>
  ) : (
    <Dialog.Root open={currentOpen} onOpenChange={setOpen}>{content}</Dialog.Root>
  );
}

export type ResponsiveDialogTriggerProps = React.ComponentPropsWithoutRef<"button"> & {
  render?: React.ReactElement;
};

export function ResponsiveDialogTrigger(props: ResponsiveDialogTriggerProps) {
  const { mobile } = useResponsiveDialogContext();
  return mobile ? <BottomSheetTrigger {...props} /> : <Dialog.Trigger data-slot="responsive-dialog-trigger" {...props} />;
}

export type ResponsiveDialogContentProps = {
  className?: string;
  children?: React.ReactNode;
  id?: string;
  initialFocus?: Dialog.Popup.Props["initialFocus"];
  finalFocus?: Dialog.Popup.Props["finalFocus"];
};

export function ResponsiveDialogContent({ className, children, ...props }: ResponsiveDialogContentProps) {
  const { mobile } = useResponsiveDialogContext();

  if (mobile) {
    return <BottomSheetContent className={className} {...props}>{children}</BottomSheetContent>;
  }

  return (
    <Dialog.Portal>
      <Dialog.Backdrop className="fixed inset-0 z-50 bg-black/45 backdrop-blur-[2px] transition-opacity duration-200 data-[ending-style]:opacity-0 data-[starting-style]:opacity-0" />
      <Dialog.Viewport className="fixed inset-0 z-50 grid place-items-center overflow-y-auto p-5">
        <Dialog.Popup
          data-slot="responsive-dialog-content"
          className={cn(
            "w-full max-w-lg overflow-hidden rounded-2xl border border-border bg-background p-6 text-foreground shadow-[0_24px_70px_rgb(0_0_0/0.18)] outline-none transition-[opacity,transform] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] data-[ending-style]:scale-[0.97] data-[ending-style]:opacity-0 data-[starting-style]:scale-[0.97] data-[starting-style]:opacity-0",
            className,
          )}
          {...props}
        >
          {children}
        </Dialog.Popup>
      </Dialog.Viewport>
    </Dialog.Portal>
  );
}

export function ResponsiveDialogHeader(props: React.ComponentPropsWithoutRef<"div">) {
  const { mobile } = useResponsiveDialogContext();
  return mobile ? <BottomSheetHeader {...props} /> : <div data-slot="responsive-dialog-header" {...props} className={cn("mb-5 space-y-1.5", props.className)} />;
}

export function ResponsiveDialogTitle(props: Dialog.Title.Props) {
  const { mobile } = useResponsiveDialogContext();
  return mobile ? <BottomSheetTitle {...props} /> : <Dialog.Title data-slot="responsive-dialog-title" {...props} className={cn("text-lg font-semibold tracking-[-0.025em]", typeof props.className === "string" ? props.className : undefined)} />;
}

export function ResponsiveDialogDescription(props: Dialog.Description.Props) {
  const { mobile } = useResponsiveDialogContext();
  return mobile ? <BottomSheetDescription {...props} /> : <Dialog.Description data-slot="responsive-dialog-description" {...props} className={cn("text-sm leading-6 text-muted-foreground", typeof props.className === "string" ? props.className : undefined)} />;
}

export function ResponsiveDialogClose(props: Dialog.Close.Props) {
  const { mobile } = useResponsiveDialogContext();
  return mobile ? <BottomSheetClose {...props} /> : <Dialog.Close data-slot="responsive-dialog-close" {...props} />;
}

export const ResponsiveDialog = Object.assign(ResponsiveDialogRoot, {
  Trigger: ResponsiveDialogTrigger,
  Content: ResponsiveDialogContent,
  Header: ResponsiveDialogHeader,
  Title: ResponsiveDialogTitle,
  Description: ResponsiveDialogDescription,
  Close: ResponsiveDialogClose,
});

"use client";

import * as React from "react";
import { Drawer } from "@base-ui/react/drawer";

import { cn } from "@/lib/utils";

export type BottomSheetProps = Drawer.Root.Props;

export function BottomSheetRoot({ swipeDirection = "down", ...props }: BottomSheetProps) {
  return <Drawer.Root swipeDirection={swipeDirection} {...props} />;
}

export function BottomSheetTrigger({ className, ...props }: Drawer.Trigger.Props) {
  return (
    <Drawer.Trigger
      data-slot="bottom-sheet-trigger"
      className={cn("outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2", typeof className === "string" ? className : undefined)}
      {...props}
    />
  );
}

export type BottomSheetContentProps = Omit<Drawer.Popup.Props, "className" | "style"> & {
  className?: string;
  contentClassName?: string;
  backdropClassName?: string;
  showHandle?: boolean;
  style?: React.CSSProperties;
};

export function BottomSheetContent({
  className,
  contentClassName,
  backdropClassName,
  showHandle = true,
  children,
  style,
  ...props
}: BottomSheetContentProps) {
  return (
    <Drawer.VirtualKeyboardProvider>
      <Drawer.Portal>
        <Drawer.Backdrop
          data-slot="bottom-sheet-backdrop"
          className={cn(
            "fixed inset-0 z-50 bg-black/48 backdrop-blur-[2px] opacity-[calc(1-var(--drawer-swipe-progress,0))] transition-opacity duration-300 data-[ending-style]:opacity-0 data-[starting-style]:opacity-0 data-[swiping]:duration-0",
            backdropClassName,
          )}
        />
        <Drawer.Viewport
          data-slot="bottom-sheet-viewport"
          className="pointer-events-none fixed inset-0 z-50 flex items-end justify-center"
        >
          <Drawer.Popup
            data-slot="bottom-sheet-content"
            className={cn(
              "pointer-events-auto relative flex max-h-[min(92dvh,56rem)] w-full flex-col overflow-hidden rounded-t-[1.75rem] border border-border/80 bg-background text-foreground shadow-[0_-18px_60px_rgb(0_0_0/0.18)] outline-none transition-[transform,translate] duration-[calc(var(--drawer-swipe-strength,1)*300ms)] ease-[cubic-bezier(0.32,0.72,0,1)] data-[ending-style]:translate-y-full data-[starting-style]:translate-y-full data-[swiping]:duration-0 sm:max-w-xl",
              className,
            )}
            style={{
              transform: "translateY(calc(var(--drawer-snap-point-offset, 0px) + var(--drawer-swipe-movement-y, 0px)))",
              ...style,
            }}
            {...props}
          >
            {showHandle ? (
              <div className="flex shrink-0 touch-none justify-center px-4 pb-2 pt-3" aria-hidden="true">
                <div className="h-1.5 w-11 rounded-full bg-muted-foreground/28" />
              </div>
            ) : null}
            <Drawer.Content
              className={cn(
                "min-h-0 overflow-y-auto overscroll-contain px-5 pb-[calc(1.25rem+var(--pwa-safe-bottom,env(safe-area-inset-bottom,0px)))]",
                contentClassName,
              )}
            >
              {children}
            </Drawer.Content>
          </Drawer.Popup>
        </Drawer.Viewport>
      </Drawer.Portal>
    </Drawer.VirtualKeyboardProvider>
  );
}

export function BottomSheetHeader({ className, ...props }: React.ComponentPropsWithoutRef<"div">) {
  return <div data-slot="bottom-sheet-header" className={cn("mb-5 space-y-1.5 text-left", className)} {...props} />;
}

export function BottomSheetFooter({ className, ...props }: React.ComponentPropsWithoutRef<"div">) {
  return <div data-slot="bottom-sheet-footer" className={cn("sticky bottom-0 mt-5 flex flex-col-reverse gap-2 bg-background pb-[var(--drawer-keyboard-inset,0px)] sm:flex-row sm:justify-end", className)} {...props} />;
}

export function BottomSheetTitle({ className, ...props }: Drawer.Title.Props) {
  return <Drawer.Title data-slot="bottom-sheet-title" className={cn("text-lg font-semibold tracking-[-0.025em]", typeof className === "string" ? className : undefined)} {...props} />;
}

export function BottomSheetDescription({ className, ...props }: Drawer.Description.Props) {
  return <Drawer.Description data-slot="bottom-sheet-description" className={cn("text-sm leading-6 text-muted-foreground", typeof className === "string" ? className : undefined)} {...props} />;
}

export function BottomSheetClose({ className, ...props }: Drawer.Close.Props) {
  return <Drawer.Close data-slot="bottom-sheet-close" className={cn("outline-none focus-visible:ring-2 focus-visible:ring-ring", typeof className === "string" ? className : undefined)} {...props} />;
}

export const BottomSheet = Object.assign(BottomSheetRoot, {
  Trigger: BottomSheetTrigger,
  Content: BottomSheetContent,
  Header: BottomSheetHeader,
  Footer: BottomSheetFooter,
  Title: BottomSheetTitle,
  Description: BottomSheetDescription,
  Close: BottomSheetClose,
});

"use client";

import * as React from "react";

export function useMediaQuery(query: string, defaultValue = false) {
  const [matches, setMatches] = React.useState(defaultValue);

  React.useEffect(() => {
    const media = window.matchMedia(query);
    const update = () => setMatches(media.matches);

    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, [query]);

  return matches;
}
